    }

    [[nodiscard]] CSkeletonInstance* GetSkeletonInstance() const noexcept { return m_pSkeletonInstance; }
    [[nodiscard]] C_BaseAnimGraphController& GetAnimGraphController() noexcept { return m_animController; }
