struct PathResult {
    enum class EStatus : std::uint32_t {
        Success               = 0,
        Failed_NoStartArea    = 1,
        Failed_NoGoalArea     = 2,
        Failed_NoPath         = 3,
        Failed_LengthExceeded = 4
