        "PlusN",
        "PushOneLeftDeltaZeroRightZero",
        "PushOneLeftDeltaZeroRightNonZero",
        "PushOneLeftDeltaOneRightZero",
        "PushOneLeftDeltaOneRightNonZero",
        "PushOneLeftDeltaNRightZero",
        "PushOneLeftDeltaNRightNonZero",
