    [[nodiscard]] static float DecodeAmbisonicsToSpeaker(
        const AmbisonicsBFormat& bFormat,
        const shared::Vector3D& speakerDirectionNormalized,
        AmbisonicsOrder order = AmbisonicsOrder::Order2
    ) noexcept;

